import { z } from "zod";
import raw from "./manifest.json";

/**
 * Centralised release manifest. Generated by scripts/generate-release-manifest.mjs
 * from real build artifacts. An entry is downloadable only if it is published,
 * has an https URL and a SHA-256 checksum.
 */
const ReleaseSchema = z.object({
  platform: z.enum(["macos", "windows"]),
  arch: z.enum(["aarch64", "x86_64", "universal"]),
  version: z.string(),
  format: z.enum(["dmg", "app-tar", "nsis-exe", "msi", "msix"]),
  status: z.enum(["published", "unpublished"]),
  url: z.string().url().startsWith("https://").nullable(),
  sha256: z.string().regex(/^[a-f0-9]{64}$/).nullable(),
  sizeBytes: z.number().int().positive().nullable(),
  releaseDate: z.string().nullable(),
  signed: z.boolean(),
  notarized: z.boolean(),
  minOs: z.string(),
});

const ManifestSchema = z.object({
  schemaVersion: z.literal(1),
  product: z.string(),
  channel: z.string(),
  releases: z.array(ReleaseSchema),
  notes: z.array(z.string()),
});

export type Release = z.infer<typeof ReleaseSchema>;

export const manifest = ManifestSchema.parse(raw);

export function isDownloadable(r: Release): r is Release & { url: string; sha256: string } {
  return r.status === "published" && !!r.url && !!r.sha256;
}

export const ARCH_LABEL: Record<Release["arch"], string> = {
  aarch64: "Apple silicon (arm64)",
  x86_64: "x64",
  universal: "Universal (Apple silicon + Intel)",
};

export const FORMAT_LABEL: Record<Release["format"], string> = {
  dmg: "Disk image (.dmg)",
  "app-tar": "App archive (.app.tar.gz)",
  "nsis-exe": "Installer (.exe, NSIS)",
  msi: "Windows Installer (.msi)",
  msix: "MSIX package",
};

export function formatBytes(n: number) {
  return n > 1e6 ? `${(n / 1e6).toFixed(1)} MB` : `${Math.round(n / 1e3)} KB`;
}
